/**
 * ensureDeviceConnectorWired — device-pin conflict against real Postgres.
 *
 * `idx_connections_org_connector_device_live` is UNIQUE on
 * (organization_id, connector_key, device_worker_id) WHERE deleted_at IS NULL
 * AND device_worker_id IS NOT NULL.
 *
 * The reconcile pass looks a connection up by (org, connector, auth_profile_id
 * IS NULL) and takes `ORDER BY id ASC LIMIT 1`, so when an org holds two live
 * rows for the same connector it always picks the older one — then pins it to
 * the single fresh device. If the NEWER row already holds that device, the
 * UPDATE violates the index, aborts the surrounding transaction, and the whole
 * wire attempt fails. Every poll. Forever.
 *
 * Observed on prod 2026-07-29: org 8dc12bdd had apple.computer_use rows 397 and
 * 447 pinned to two different devices, emitting 21 identical
 * "[device-connectors] Failed to wire device connector /
 * duplicate key value violates unique constraint" errors in a 10-minute window.
 */

import { afterAll, beforeEach, describe, expect, it } from 'vitest';
import { cleanupTestDatabase, getTestDb } from '../setup/test-db';
import { createTestOrganization, createTestUser } from '../setup/test-fixtures';

const sql = getTestDb();
const CONNECTOR = 'apple.computer_use';

async function seedWorker(userId: string, orgId: string): Promise<string> {
  const workerId = `dev-${Math.random().toString(36).slice(2, 10)}`;
  const [row] = (await sql`
    INSERT INTO device_workers (
      user_id, worker_id, platform, capabilities, label, organization_id, last_seen_at
    ) VALUES (
      ${userId}, ${workerId}, 'macos',
      ${sql.json(['computer.use'])}, 'Test Mac', ${orgId}, NOW()
    )
    RETURNING id
  `) as unknown as Array<{ id: string }>;
  return String(row.id);
}

async function seedConn(
  orgId: string,
  userId: string,
  deviceWorkerId: string | null
): Promise<number> {
  const slug = `cu-${Math.random().toString(36).slice(2, 8)}`;
  const [row] = (await sql`
    INSERT INTO connections (
      organization_id, connector_key, slug, display_name, status,
      auth_profile_id, created_by, visibility, device_worker_id, created_at, updated_at
    ) VALUES (
      ${orgId}, ${CONNECTOR}, ${slug}, 'Computer Use', 'active',
      NULL, ${userId}, 'private', ${deviceWorkerId}::uuid, NOW(), NOW()
    )
    RETURNING id
  `) as unknown as Array<{ id: number }>;
  return Number(row.id);
}

/**
 * The exact statement `reconcilePin` runs today: pin `connectionId` to `target`
 * with no guard against another live row already holding that device.
 */
async function pinUnguarded(connectionId: number, target: string) {
  await sql`
    UPDATE connections
    SET device_worker_id = ${target}::uuid, updated_at = NOW()
    WHERE id = ${connectionId}
      AND device_worker_id IS DISTINCT FROM ${target}::uuid
  `;
}

describe('device pin unique conflict', () => {
  let orgId: string;
  let userId: string;

  beforeEach(async () => {
    const org = await createTestOrganization();
    orgId = org.id;
    const user = await createTestUser({ organizationId: orgId });
    userId = user.id;
  });

  afterAll(async () => {
    await cleanupTestDatabase();
  });

  it('reproduces the prod failure: pinning the older row to a device the newer row holds', async () => {
    const deviceA = await seedWorker(userId, orgId);
    const deviceB = await seedWorker(userId, orgId);

    // Two live rows for one (org, connector) — the prod shape (ids 397 / 447).
    const older = await seedConn(orgId, userId, deviceA);
    const newer = await seedConn(orgId, userId, deviceB);
    expect(older).toBeLessThan(newer);

