it('clears the retired pin regardless of which row the fast path selects first', async () => {
  // Insert the CURRENT (correctly pinned) connection FIRST, so it has the
  // lower id. An unordered `GROUP BY … LIMIT 1` would tend to return it, and
  // the pin UPDATE would no-op on a row that is already correct — leaving the
  // retired connection pinned to a vanished device forever. The fast path
  // orders repair-first precisely so this cannot happen, and this test fails
  // if that ORDER BY is ever dropped.
